from db import connect_db

def find_all_notes():
    """모든 관찰 메모 목록 조회 (최신순 정렬)"""
    with connect_db() as conn:
        return conn.execute(
            """SELECT id, title, content, status, created_at, updated_at
               FROM notes
               ORDER BY id DESC"""
        ).fetchall()

def find_note_by_id(note_id: int):
    """특정 메모 상세 조회 (매개변수 바인딩 %s 사용)"""
    with connect_db() as conn:
        return conn.execute(
            """SELECT id, title, content, status, created_at, updated_at
               FROM notes
               WHERE id = %s""",
            (note_id,),
        ).fetchone()

def insert_note(title: str, content: str, status: str = "확인 전"):
    """새 관찰 메모 작성 및 생성된 레코드 반환 (매개변수 바인딩 %s 사용)"""
    with connect_db() as conn:
        return conn.execute(
            """INSERT INTO notes (title, content, status)
               VALUES (%s, %s, %s)
               RETURNING id, title, content, status, created_at, updated_at""",
            (title, content, status),
        ).fetchone()

def update_note(note_id: int, title: str, content: str, status: str = None):
    """기존 메모 수정 및 갱신된 레코드 반환 (매개변수 바인딩 %s 사용)"""
    with connect_db() as conn:
        if status:
            return conn.execute(
                """UPDATE notes
                   SET title = %s, content = %s, status = %s, updated_at = NOW()
                   WHERE id = %s
                   RETURNING id, title, content, status, created_at, updated_at""",
                (title, content, status, note_id),
            ).fetchone()
        else:
            return conn.execute(
                """UPDATE notes
                   SET title = %s, content = %s, updated_at = NOW()
                   WHERE id = %s
                   RETURNING id, title, content, status, created_at, updated_at""",
                (title, content, note_id),
            ).fetchone()

def delete_note(note_id: int):
    """특정 메모 삭제 (매개변수 바인딩 %s 사용)"""
    with connect_db() as conn:
        result = conn.execute(
            "DELETE FROM notes WHERE id = %s",
            (note_id,),
        )
        return result.rowcount > 0

from flask import Blueprint, request, session
from werkzeug.security import check_password_hash
from repositories.user_repo import find_user_by_username

auth_bp = Blueprint("auth", __name__, url_prefix="/api/auth")

@auth_bp.post("/login")
def login():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return {"error": "아이디와 비밀번호를 JSON으로 보내 주세요."}, 400

    username = data.get("username")
    password = data.get("password")

    if not isinstance(username, str) or not isinstance(password, str):
        return {"error": "아이디와 비밀번호를 문자열로 보내 주세요."}, 400

    username_trimmed = username.strip()
    password_trimmed = password.strip()

    if not username_trimmed or not password_trimmed:
        return {"error": "아이디와 비밀번호를 모두 입력해 주세요."}, 400

    user = find_user_by_username(username_trimmed)
    if user is None or not check_password_hash(user["password_hash"], password):
        return {"error": "아이디 또는 비밀번호가 올바르지 않습니다."}, 401

    # 세션에 로그인 정보 저장 (심화 4: 세션 유지 지원)
    session["user_id"] = user["id"]
    session["username"] = user["username"]

    return {
        "message": "로그인 성공",
        "user": {"id": user["id"], "username": user["username"]},
    }, 200

@auth_bp.post("/logout")
def logout():
    session.clear()
    return {"message": "로그아웃되었습니다."}, 200

@auth_bp.get("/me")
def get_current_user():
    user_id = session.get("user_id")
    username = session.get("username")
    if user_id and username:
        return {"user": {"id": user_id, "username": username}}, 200
    return {"user": None}, 200

