from repositories.event_repo import insert_event, find_events, get_events_summary

events_bp = Blueprint("events", __name__, url_prefix="/api/events")

def make_event(data):
    if not isinstance(data, dict):
        return None

    method = data.get("method")
    path = data.get("path")
    status = data.get("status_code")
    allowed_methods = {"GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"}
    if not isinstance(method, str) or method not in allowed_methods:
        return None
    if not isinstance(path, str) or not path.startswith("/") or len(path) > 500:
        return None
    if type(status) is not int or not 100 <= status <= 599:
        return None

    if method == "POST" and path == "/auth/login" and status == 200:
        event_type = "login_success"
    elif method == "POST" and path == "/auth/login" and status == 401:
        event_type = "login_failure"
    else:
        event_type = "http_request"

    return {
        "method": method,
        "path": path,
        "status_code": status,
        "event_type": event_type,
    }

@events_bp.post("")
def receive_event():
    """일반 서비스가 보낸 요청 기록 수신 및 DB 저장"""
    event = make_event(request.get_json(silent=True))
    if event is None:
        return {"error": "method, path, status_code를 올바르게 보내 주세요."}, 400

    try:
        insert_event(
            method=event["method"],
            path=event["path"],
            status_code=event["status_code"],
            event_type=event["event_type"],
        )
    except psycopg.Error:
        return {"error": "감시 기록을 저장할 수 없습니다."}, 503

    return {"message": "기록을 받았습니다."}, 201

@events_bp.get("")
def get_events():
    """요청 기록 조회 (심화 4: 비로그인 접근 제한, 심화 1: 검색/필터링, 심화 2: 요약 통계)"""
    if "user_id" not in session:
        return {"error": "로그인이 필요합니다."}, 401

    event_type = request.args.get("event_type")
    allowed = {"login_success", "login_failure", "http_request"}
    if event_type is not None and event_type not in allowed:
        return {"error": "지원하지 않는 이벤트 종류입니다."}, 400

    path = request.args.get("path")
    status_code_raw = request.args.get("status_code")
    status_code = None
    if status_code_raw:
        try:
            status_code = int(status_code_raw)
        except ValueError:
            return {"error": "올바른 상태 코드를 입력해 주세요."}, 400

    try:
        rows = find_events(event_type=event_type, path=path, status_code=status_code, limit=50)
        summary = get_events_summary(limit=50)
    except psycopg.Error:
        return {"error": "감시 기록을 조회할 수 없습니다."}, 503

    for row in rows:
        row["occurred_at"] = row["occurred_at"].isoformat()

    return {
        "events": rows,
        "summary": summary,
    }, 200

