        return {"error": "로그인이 필요합니다."}, 401

    try:
        rows = find_all_notes()
    except psycopg.Error:
        return {"error": "메모 목록을 조회할 수 없습니다."}, 503

    return {"notes": [format_note(r) for r in rows]}, 200

